import { test, expect } from '@playwright/test';

test.describe('Image Upload - Error for Small Dimensions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display error message when image dimensions are too small', async ({ page }) => {
    // Setup: Intercept the API call to get image dimensions
    await page.route('**/api/upload/validate-dimensions', (route) => {
      route.abort('failed');
    });

    // Setup: Mock the API response for small image dimensions
    await page.route('**/api/upload/validate-dimensions', (route) => {
      route.continue();
    });

    // Setup: Mock the API response for successful validation
    await page.route('**/api/upload/validate-dimensions', (route) => {
      route.continue();
    });

    // Setup: Mock the API response for failed validation
    await page.route('**/api/upload/validate-dimensions', (route) => {
      route.abort('failed');
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await expect(fileInput).toBeVisible();

    // Get the error message using getByText
    const errorMessage = page.getByText('Image dimensions are too small');
    await expect(errorMessage).toBeVisible();

    // Get the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Get the file preview using getByRole
    const filePreview = page.getByRole('img', { name: /preview/i });
    await expect(filePreview).toBeVisible();

    // Verify error message is displayed
    await expect(errorMessage).toContainText('too small');

    // Verify upload button is disabled
    await expect(uploadButton).toBeDisabled();

    // Verify file preview is visible
    await expect(filePreview).toBeVisible();
  });

  test('should not display error when image dimensions are valid', async ({ page }) => {
    // Setup: Mock the API response for valid image dimensions
    await page.route('**/api/upload/validate-dimensions', (route) => {
      route.continue();
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await expect(fileInput).toBeVisible();

    // Get the error message using getByText
    const errorMessage = page.getByText('Image dimensions are too small');
    await expect(errorMessage).not.toBeVisible();

    // Get the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Get the file preview using getByRole
    const filePreview = page.getByRole('img', { name: /preview/i });
    await expect(filePreview).toBeVisible();

    // Verify error message is not displayed
    await expect(errorMessage).not.toBeVisible();

    // Verify upload button is enabled
    await expect(uploadButton).not.toBeDisabled();

    // Verify file preview is visible
    await expect(filePreview).toBeVisible();
  });
});
